"use client";
// Draws the chart with Plotly from a spec computed on the server.
// The chart code is fixed; nothing here is generated by AI.
import { useEffect, useRef } from "react";
import type { ChartSpec } from "@/lib/executor";
import { fmt, fmtPct } from "@/lib/format";
import type { Lang } from "@/lib/catalog";

const COLORS = ["#0b6e4f", "#e07a1f", "#3a6ea5", "#a23b72"];

export default function Chart({ spec, lang, pct }: { spec: ChartSpec; lang: Lang; pct: boolean }) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (spec.type === "kpi" || spec.type === "table" || !ref.current) return;
    let cancelled = false;
    const el = ref.current;
    import("plotly.js-basic-dist-min").then((mod) => {
      if (cancelled) return;
      const Plotly = (mod as unknown as { default: typeof import("plotly.js-basic-dist-min") }).default ?? mod;
      const multiYear = spec.series.some((s) => s.points.length > 1);
      const data = multiYear
        ? spec.series.map((s, i) => ({
            type: spec.type === "bar" ? ("bar" as const) : ("scatter" as const),
            mode: "lines+markers" as const,
            name: s.label,
            x: s.points.map((p) => p.year),
            y: s.points.map((p) => p.value),
            marker: { color: COLORS[i % COLORS.length] },
            line: { width: 3 },
          }))
        : [
            {
              type: "bar" as const,
              x: spec.series.map((s) => s.label),
              y: spec.series.map((s) => s.points[0]?.value ?? null),
              marker: { color: spec.series.map((_, i) => COLORS[i % COLORS.length]) },
              text: spec.series.map((s) => (s.points[0] ? (pct ? fmtPct(s.points[0].value, lang) : fmt(s.points[0].value, lang)) : "")),
              textposition: "outside" as const,
            },
          ];
      Plotly.newPlot(
        el,
        data,
        {
          margin: { l: 50, r: 10, t: 10, b: 40 },
          height: 300,
          showlegend: spec.series.length > 1 && multiYear,
          legend: { orientation: "h", y: -0.2 },
          yaxis: { title: { text: spec.unit }, automargin: true, separatethousands: true },
          xaxis: { automargin: true, ...(multiYear ? { dtick: undefined } : {}) },
          separators: lang === "az" ? ", " : ".,",
          paper_bgcolor: "rgba(0,0,0,0)",
          plot_bgcolor: "rgba(0,0,0,0)",
          font: { family: "system-ui, sans-serif", size: 13 },
        },
        { displayModeBar: false, responsive: true },
      );
    });
    return () => {
      cancelled = true;
    };
  }, [spec, lang, pct]);

  if (spec.type === "kpi") {
    const s = spec.series[0];
    const p = s?.points[s.points.length - 1];
    if (!p) return null;
    return (
      <div className="kpi">
        <div className="kpi-value">{pct ? fmtPct(p.value, lang) : fmt(p.value, lang)}</div>
        <div className="kpi-label">
          {s.label} · {p.year} · {spec.unit}
        </div>
      </div>
    );
  }
  if (spec.type === "table") return null;
  return <div ref={ref} className="chart" role="img" aria-label={spec.title} />;
}
